const pieceName:Record<string,string>={p:'Piyon',n:'At',b:'Fil',r:'Kale',q:'Vezir',k:'Åah'};
const values:Record<string,number>={p:100,n:320,b:330,r:500,q:900,k:0};

type Snapshot={fen:string;beforeFen:string;move:Move;eval:number;turn:'w'|'b';engineEval?:number;beforeEngineEval?:number;bestMove?:string|null;depth?:number};
function formatTime(sec:number){const m=Math.floor(sec/60).toString().padStart(2,'0');const s=(sec%60).toString().padStart(2,'0');return `${m}:${s}`;}
function materialEval(g:Chess){let score=0;for(const row of g.board())for(const p of row)if(p)score+=(p.color==='w'?1:-1)*values[p.type];return score;}
function labelLoss(loss:number){if(loss>=250)return{label:'BÃ¼yÃ¼k hata',tone:'bad'};if(loss>=100)return{label:'Hata',tone:'bad'};if(loss>=45)return{label:'ÅÃ¼pheli',tone:'warn'};return{label:'Ä°yi',tone:'good'};}
function snapshotsFromHistory(items:any[]):Snapshot[]{
  const g=new Chess();
  const out:Snapshot[]=[];
  for(const item of items){
    try{
      const beforeFen=g.fen();
      const move=g.move({from:item.from,to:item.to,promotion:item.promotion||undefined});
      if(move){out.push({fen:g.fen(),beforeFen,move,eval:materialEval(g),turn:move.color});}
    }catch{}
  }
  return out;
}

