 const reset=()=>{if(onlineColor)return;if(history.length&&game.isGameOver())persistFinished();const g=new Chess();setGame(g);setFen(g.fen());setSelected(null);setHistory([]);setSnapshots([]);setLast(null);setWhiteTime(600);setBlackTime(600);setRunning(false);setMessage('Beyaz baÅŸlar');setReview(false);setReviewIndex(-1)};
 const select=(sq:Square)=>{if(puzzleMode){const piece=game.get(sq);if(!selected){if(piece?.color===game.turn())setSelected(sq);return;}if(selected===sq){setSelected(null);return;}puzzleMove(selected,sq);return;}if(review)return;if(!running&&history.length>0&&!onlineColor)return;if(game.isGameOver()&&!onlineColor)return;const piece=game.get(sq);if(!selected){if(piece?.color===game.turn()){setSelected(sq);setMessage(`${pieceName[piece.type]} seÃ§ildi â€” hedef kareyi seÃ§`)}return;}if(selected===sq){setSelected(null);setMessage(`${game.turn()==='w'?'Beyaz':'Siyah'} oynuyor`);return;}if(onlineColor&&onlineTurn&&onlineTurn!==onlineColor){setMessage('SÄ±ra rakibinizde');return;}try{if(socket?.readyState===WebSocket.OPEN&&onlineColor){socket.send(JSON.stringify({type:'game:move',from:selected,to:sq,promotion:'q',color:onlineColor}));setSelected(null);setMessage('Hamle sunucu tarafÄ±ndan doÄŸrulanÄ±yorâ€¦');return;}const beforeFen=game.fen();const move=game.move({from:selected,to:sq,promotion:'q'});if(move){const after=materialEval(game);const snap:Snapshot={fen:game.fen(),beforeFen,move,eval:after,turn:move.color};setHistory([...game.history({verbose:true})]);setSnapshots((s:Snapshot[])=>[...s,snap]);setLast(move);setFen(game.fen());setSelected(null);setRunning(true);const over=game.isGameOver();if(over){setRunning(false);setTimeout(persistFinished,0);if(game.isCheckmate())setMessage(`${move.color==='w'?'Beyaz':'Siyah'} mat yaptÄ± â€” oyun bitti`);else if(game.isDraw())setMessage('Berabere â€” oyun bitti');else setMessage('Oyun bitti');}else if(game.isCheck())setMessage(`${game.turn()==='w'?'Beyaz':'Siyah'} ÅŸah Ã§ekildi`);else setMessage(`${game.turn()==='w'?'Beyaz':'Siyah'} oynuyor`);}else setMessage('Bu hamle yasal deÄŸil');}catch{setMessage('Bu hamle yasal deÄŸil');}};
